CREATE TABLE IF NOT EXISTS survey_question_catalog (
  survey_type VARCHAR(30) NOT NULL CHECK (survey_type IN ('farmer','stakeholder')),
  question_id TEXT NOT NULL,
  question_number TEXT,
  question_text_hi TEXT NOT NULL,
  question_text_en TEXT NOT NULL,
  question_text_as TEXT NOT NULL,
  answer_column TEXT NOT NULL,
  answer_type TEXT NOT NULL,
  PRIMARY KEY (survey_type, question_id)
);

