INSERT INTO survey_question_catalog (survey_type,question_id,question_number,question_text_hi,question_text_en,question_text_as,answer_column,answer_type) VALUES ('stakeholder', 'fpo_top_modules', '13', 'आपके अनुसार खुशहाल किसान के कौन-से तीन मॉड्यूल आपके एफपीओ के किसानों के लिए सबसे अधिक उपयोगी होंगे? (अधिकतम 3 विकल्प चुनें)', 'Which three Khushhal Kisan modules would be most useful for farmers in your FPO? (Select up to 3)', 'আপোনাৰ মতে খুশহাল কিষাণৰ কোন তিনিটা মডিউল আপোনাৰ FPO-ৰ কৃষকৰ বাবে আটাইতকৈ উপযোগী হ’ব? (সৰ্বাধিক ৩টা বাছনি কৰক)', 'fpo_top_modules', 'checks') ON CONFLICT (survey_type,question_id) DO UPDATE SET question_number=EXCLUDED.question_number, question_text_hi=EXCLUDED.question_text_hi, question_text_en=EXCLUDED.question_text_en, question_text_as=EXCLUDED.question_text_as, answer_column=EXCLUDED.answer_column, answer_type=EXCLUDED.answer_type;
INSERT INTO survey_question_catalog (survey_type,question_id,question_number,question_text_hi,question_text_en,question_text_as,answer_column,answer_type) VALUES ('stakeholder', 'fpo_app_interest', '14', 'क्या आपका एफपीओ एआई आधारित किसान सहायता मोबाइल एप्लिकेशन अपनाने में रुचि रखता है?', 'Is your FPO interested in adopting an AI-based farmer-support mobile application?', 'আপোনাৰ FPO-এ AI-ভিত্তিক কৃষক সহায়ক ম’বাইল এপ গ্ৰহণ কৰিবলৈ আগ্ৰহী নে?', 'fpo_app_interest', 'radio') ON CONFLICT (survey_type,question_id) DO UPDATE SET question_number=EXCLUDED.question_number, question_text_hi=EXCLUDED.question_text_hi, question_text_en=EXCLUDED.question_text_en, question_text_as=EXCLUDED.question_text_as, answer_column=EXCLUDED.answer_column, answer_type=EXCLUDED.answer_type;
INSERT INTO survey_question_catalog (survey_type,question_id,question_number,question_text_hi,question_text_en,question_text_as,answer_column,answer_type) VALUES ('stakeholder', 'fpo_support_needed', '15', 'इस एप्लिकेशन को अपने एफपीओ में लागू करने के लिए आपको किस प्रकार की सहायता की आवश्यकता होगी? (एक से अधिक विकल्प चुन सकते हैं)', 'What support would you need to implement this application in your FPO? (Select all that apply)', 'আপোনাৰ FPO-ত এই এপ্লিকেশ্যন ৰূপায়ণ কৰিবলৈ কেনেধৰণৰ সহায়ৰ প্ৰয়োজন হ’ব? (একাধিক বিকল্প বাছনি কৰিব পাৰে)', 'fpo_support_needed', 'checks') ON CONFLICT (survey_type,question_id) DO UPDATE SET question_number=EXCLUDED.question_number, question_text_hi=EXCLUDED.question_text_hi, question_text_en=EXCLUDED.question_text_en, question_text_as=EXCLUDED.question_text_as, answer_column=EXCLUDED.answer_column, answer_type=EXCLUDED.answer_type;
INSERT INTO survey_question_catalog (survey_type,question_id,question_number,question_text_hi,question_text_en,question_text_as,answer_column,answer_type) VALUES ('stakeholder', 'fpo_training_ready', '16', 'क्या आपका एफपीओ खुशहाल किसान के लिए किसानों के बीच जागरूकता एवं प्रशिक्षण कार्यक्रम आयोजित करने के लिए तैयार होगा?', 'Would your FPO be willing to organise farmer awareness and training programmes for Khushhal Kisan?', 'খুশহাল কিষাণৰ বাবে কৃষকৰ মাজত সজাগতা আৰু প্ৰশিক্ষণ কাৰ্যসূচী আয়োজন কৰিবলৈ আপোনাৰ FPO সাজু হ’বনে?', 'fpo_training_ready', 'radio') ON CONFLICT (survey_type,question_id) DO UPDATE SET question_number=EXCLUDED.question_number, question_text_hi=EXCLUDED.question_text_hi, question_text_en=EXCLUDED.question_text_en, question_text_as=EXCLUDED.question_text_as, answer_column=EXCLUDED.answer_column, answer_type=EXCLUDED.answer_type;
