INSERT INTO survey_question_catalog (survey_type,question_id,question_number,question_text_hi,question_text_en,question_text_as,answer_column,answer_type) VALUES ('stakeholder', 'fpo_improvement', '18', 'आपके अनुसार किसानों के लिए कृषि तकनीक में सबसे महत्वपूर्ण सुधार क्या होना चाहिए?', 'In your opinion, what is the most important improvement needed in agricultural technology for farmers?', 'আপোনাৰ মতে কৃষকৰ বাবে কৃষি প্ৰযুক্তিত আটাইতকৈ গুৰুত্বপূৰ্ণ উন্নতি কি হোৱা উচিত?', 'fpo_improvement', 'radio') ON CONFLICT (survey_type,question_id) DO UPDATE SET question_number=EXCLUDED.question_number, question_text_hi=EXCLUDED.question_text_hi, question_text_en=EXCLUDED.question_text_en, question_text_as=EXCLUDED.question_text_as, answer_column=EXCLUDED.answer_column, answer_type=EXCLUDED.answer_type;
INSERT INTO survey_question_catalog (survey_type,question_id,question_number,question_text_hi,question_text_en,question_text_as,answer_column,answer_type) VALUES ('stakeholder', 'fpo_recommend', '19', 'यदि खुशहाल किसान का पायलट प्रोग्राम सकारात्मक परिणाम देता है, तो क्या आप इसे अन्य एफपीओ के साथ साझा करने की अनुशंसा करेंगे?', 'If the Khushhal Kisan pilot programme delivers positive results, would you recommend it to other FPOs?', 'খুশহাল কিষাণৰ পাইলট কাৰ্যসূচীয়ে ইতিবাচক ফলাফল দিলে আপুনি ইয়াক আন FPO-সমূহক পৰামৰ্শ দিবনে?', 'fpo_recommend', 'radio') ON CONFLICT (survey_type,question_id) DO UPDATE SET question_number=EXCLUDED.question_number, question_text_hi=EXCLUDED.question_text_hi, question_text_en=EXCLUDED.question_text_en, question_text_as=EXCLUDED.question_text_as, answer_column=EXCLUDED.answer_column, answer_type=EXCLUDED.answer_type;
INSERT INTO survey_question_catalog (survey_type,question_id,question_number,question_text_hi,question_text_en,question_text_as,answer_column,answer_type) VALUES ('stakeholder', 'fpo_followup', '20', 'क्या आप खुशहाल किसान के पायलट प्रोग्राम के संबंध में संपर्क प्राप्त करना चाहेंगे?', 'Would you like to be contacted about the Khushhal Kisan pilot programme?', 'খুশহাল কিষাণৰ পাইলট কাৰ্যসূচীৰ বিষয়ে আপোনাৰ সৈতে যোগাযোগ কৰাটো বিচাৰেনে?', 'fpo_followup', 'radio') ON CONFLICT (survey_type,question_id) DO UPDATE SET question_number=EXCLUDED.question_number, question_text_hi=EXCLUDED.question_text_hi, question_text_en=EXCLUDED.question_text_en, question_text_as=EXCLUDED.question_text_as, answer_column=EXCLUDED.answer_column, answer_type=EXCLUDED.answer_type;
