CREATE SEQUENCE IF NOT EXISTS public.survey_fpo_code_seq START WITH 1 INCREMENT BY 1;
SELECT setval('public.survey_pending_new_code_seq',
  COALESCE((SELECT MAX((regexp_match(response_id, '^EKK-([0-9]+)$'))[1]::BIGINT) FROM survey_responses WHERE response_id ~ '^EKK-[0-9]+$'),0)+1,
  false);
SELECT setval('public.survey_akk_code_seq',
  COALESCE((SELECT MAX((regexp_match(response_id, '^AKK-([0-9]+)$'))[1]::BIGINT) FROM survey_responses WHERE response_id ~ '^AKK-[0-9]+$'),0)+1,
  false);
SELECT setval('public.survey_fpo_code_seq',
  COALESCE((SELECT MAX((regexp_match(response_id, '^FPO-([0-9]+)$'))[1]::BIGINT) FROM survey_responses WHERE response_id ~ '^FPO-[0-9]+$'),0)+1,
  false);
COMMIT;
